window.__votdWeek && window.__votdWeek({"week":"2029-06-04","reading":"Doctrine and Covenants 58–59","days":[{"d":"2029-06-04","ref":"D&C 58:2","b":"D&C","c":58,"v":2,"he":"כִּי אָמֵן אֲנִי אֹמֵר לָכֶם אַשְׁרֵי הַשֹּׁמֵר מִצְוֹתַי אִם בַּחַיִּים וְאִם בַּמָּוֶת וְהַנֶּאֱמָן בַּצָּרָה שְׂכָרוֹ גָדוֹל יוֹתֵר בְּמַלְכוּת הַשָּׁמָיִם׃","en":"For verily I say unto you, blessed is he that keepeth my commandments, whether in life or in death; and he that is faithful in tribulation, the reward of the same is greater in the kingdom of heaven."},{"d":"2029-06-05","ref":"D&C 58:21","b":"D&C","c":58,"v":21,"he":"אַל יָפֵר אִישׁ חֻקֵּי הָאָרֶץ כִּי הַשֹּׁמֵר חֻקֵּי אֱלֹהִים אֵין צֹרֶךְ לוֹ לְהָפֵר חֻקֵּי הָאָרֶץ׃","en":"Let no man break the laws of the land, for he that keepeth the laws of God hath no need to break the laws of the land."},{"d":"2029-06-06","ref":"D&C 58:42","b":"D&C","c":58,"v":42,"he":"הִנֵּה הַשָּׁב מֵחֲטָאָיו נִסְלַח לוֹ וַאֲנִי יְהוָה אֵינֶנִּי זוֹכְרָם עוֹד׃","en":"Behold, he who has repented of his sins, the same is forgiven, and I, the Lord, remember them no more."},{"d":"2029-06-07","ref":"D&C 58:43","b":"D&C","c":58,"v":43,"he":"בָּזֹאת תֵּדְעוּ אִם שָׁב אִישׁ מֵחֲטָאָיו הִנֵּה יִתְוַדֶּה עֲלֵיהֶם וְיַעַזְבֵם׃","en":"By this ye may know if a man repenteth of his sins—behold, he will confess them and forsake them."},{"d":"2029-06-08","ref":"D&C 59:2","b":"D&C","c":59,"v":2,"he":"כִּי הַחַיִּים יִירְשׁוּ הָאָרֶץ וְהַמֵּתִים יָנוּחוּ מִכׇּל עֲמָלָם וּמַעֲשֵׂיהֶם יֵלְכוּ אַחֲרֵיהֶם וִיקַבְּלוּ עֲטָרָה בִּמְעוֹנוֹת אָבִי אֲשֶׁר הֲכִינוֹתִי לָהֶם׃","en":"For those that live shall inherit the earth, and those that die shall rest from all their labors, and their works shall follow them; and they shall receive a crown in the mansions of my Father, which I have prepared for them."},{"d":"2029-06-09","ref":"D&C 59:7","b":"D&C","c":59,"v":7,"he":"תּוֹדֶה לַיהוָה אֱלֹהֶיךָ בְּכׇל דָּבָר׃","en":"Thou shalt thank the Lord thy God in all things."},{"d":"2029-06-10","ref":"D&C 59:21","b":"D&C","c":59,"v":21,"he":"וּבְאֵין דָּבָר יַעֲצִיב אָדָם אֶת־אֱלֹהִים וְאֵין אֲשֶׁר יִבְעַר בּוֹ אַפּוֹ זוּלָתִי אֵלֶּה אֲשֶׁר אֵינָם מוֹדִים בְּיָדוֹ בְּכׇל דָּבָר וְאֵינָם שֹׁמְעִים מִצְוֹתָיו׃","en":"And in nothing doth man offend God, or against none is his wrath kindled, save those who confess not his hand in all things, and obey not his commandments."}]});
